import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  MenuItem,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import { downloadUncertainWorkbook } from './downloadUncertainWorkbook';
import { categoryLabel } from './expertReviewCategories';
import ExpertReviewWizard from './ExpertReviewWizard';
import ExpertReviewPage from './ExpertReviewPage';
import ExpertReviewTogether from './ExpertReviewTogether';
import ExpertReviewLayoutControl from './ExpertReviewLayoutControl';
import { ExpertReviewLayout, readExpertReviewLayout, writeExpertReviewLayout } from './expertReviewLayout';
import {
  ExpertReviewRow,
  canSelectForSharedAssessment,
  lacksActivityQuantity,
  similarOpenRows,
} from './expertReviewDisplay';

interface CompanySummary {
  msmeId: string;
  companyName: string;
  scope: 'required' | 'all';
  openRequired: number;
  counts: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
  open: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
}

interface CorrectionAssistance {
  transactionId?: string;
  needsAssistance: boolean;
  referToRecommendation: boolean;
  message: string;
  apply?: {
    category?: string;
    quantity?: number | null;
    unit?: string;
    factorId?: string;
    factorLabel?: string;
  } | null;
}

export interface ConsultantUserSelection {
  userId: string;
  name: string;
  email: string;
  companyName: string;
  msmeId: string;
}

const approvalEffect = (name?: string) => (
  name
    ? `Analytics and report generation for ${name} now use this calculation.`
    : 'Analytics and report generation for this user now use this calculation.'
);

const ExpertCalculationReview: React.FC<{
  selectedUser?: ConsultantUserSelection;
  onBack?: () => void;
}> = ({ selectedUser, onBack }) => {
  const [companies, setCompanies] = useState<CompanySummary[]>([]);
  const [msmeId, setMsmeId] = useState(selectedUser?.msmeId || '');
  const [rows, setRows] = useState<ExpertReviewRow[]>([]);
  const [note, setNote] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [downloading, setDownloading] = useState(false);
  const [assistanceById, setAssistanceById] = useState<Record<string, CorrectionAssistance>>({});
  const [askingId, setAskingId] = useState<string | null>(null);
  const [layout, setLayout] = useState<ExpertReviewLayout>(readExpertReviewLayout);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const token = () => localStorage.getItem('token');
  const openRows = rows.filter((row) => !row.settled);
  const bulkBlocked = openRows.some(lacksActivityQuantity);

  const loadCompanies = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/calculation-review'), {
        headers: { Authorization: `Bearer ${token()}` },
      });
      const list = response.data?.data?.companies || [];
      setCompanies(list);
      setMsmeId((current) => selectedUser?.msmeId || current || list[0]?.msmeId || '');
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Failed to load companies waiting for review.');
    } finally {
      setLoading(false);
    }
  }, [selectedUser?.msmeId]);

  const loadRows = useCallback(async (companyId: string) => {
    if (!companyId) {
      setRows([]);
      return;
    }
    try {
      const response = await axios.get(buildApiUrl('/expert/calculation-review'), {
        headers: { Authorization: `Bearer ${token()}` },
        params: { msmeId: companyId },
      });
      setRows(response.data?.data?.transactions || []);
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Failed to load the company review.');
    }
  }, []);

  useEffect(() => {
    void loadCompanies();
  }, [loadCompanies]);

  useEffect(() => {
    void loadRows(msmeId);
  }, [loadRows, msmeId]);

  const confirmOne = async (row: ExpertReviewRow) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/calculation-review/confirm`),
        { note },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const kilograms = Number(row.co2Emissions || 0);
      setNotice(`Approved ${row.description || 'the voucher'} in ${categoryLabel(row.category)}. ${kilograms} kg CO2e. ${approvalEffect(selectedUser?.name)}`);
      setRows((current) => current.map((item) => (
        item._id === row._id
          ? { ...item, settled: true, settledKilograms: kilograms }
          : item
      )));
      await loadCompanies();
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The confirmation could not be saved.');
    } finally {
      setBusyId(null);
    }
  };

  const correctOne = async (row: ExpertReviewRow, draft: { category: string; quantity: string; unit: string }) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/emission-review`),
        {
          category: draft.category,
          subcategory: row.subcategory || '',
          quantity: Number(draft.quantity),
          unit: draft.unit,
          note: note || 'Corrected by the expert consultant.',
        },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const saved = response.data?.data;
      const kilograms = Number(saved?.co2Emissions || 0);
      setNotice(
        `Corrected and approved ${row.description || 'the voucher'} in ${categoryLabel(draft.category)}. `
        + `Factor ${saved?.factorId || 'applied'}. ${kilograms} kg CO2e. ${approvalEffect(selectedUser?.name)}`
      );
      setRows((current) => current.map((item) => (
        item._id === row._id
          ? {
            ...item,
            settled: true,
            settledKilograms: kilograms,
            priorKilograms: Number(item.co2Emissions || 0),
            factorId: saved?.factorId || item.factorId,
            category: draft.category,
            quantity: Number(draft.quantity),
            unit: draft.unit,
          }
          : item
      )));
      await loadCompanies();
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The correction could not be saved.');
    } finally {
      setBusyId(null);
    }
  };

  const selectedRows = rows.filter((row) => selectedIds.includes(row._id) && canSelectForSharedAssessment(row));

  const correctSelected = async (draft: { category: string; quantity: string; unit: string }) => {
    if (selectedRows.length < 2 || draft.quantity === '' || !draft.unit) return;
    setBusyId('selected');
    setError(null);
    setNotice(null);
    const done: string[] = [];
    try {
      for (const row of selectedRows) {
        const response = await axios.post(
          buildApiUrl(`/expert/transactions/${row._id}/emission-review`),
          {
            category: draft.category,
            subcategory: row.subcategory || '',
            quantity: Number(draft.quantity),
            unit: draft.unit,
            note: note || 'Corrected by the expert consultant for similar transactions.',
          },
          { headers: { Authorization: `Bearer ${token()}` } },
        );
        const saved = response.data?.data;
        const kilograms = Number(saved?.co2Emissions || 0);
        done.push(row._id);
        setRows((current) => current.map((item) => (
          item._id === row._id
            ? {
              ...item,
              settled: true,
              settledKilograms: kilograms,
              priorKilograms: Number(item.co2Emissions || 0),
              factorId: saved?.factorId || item.factorId,
              category: draft.category,
              quantity: Number(draft.quantity),
              unit: draft.unit,
            }
            : item
        )));
      }
      setNotice(
        `Corrected and approved ${done.length} transactions in ${categoryLabel(draft.category)}. ${approvalEffect(selectedUser?.name)}`
      );
      setSelectedIds([]);
      await loadCompanies();
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The shared correction could not be saved.');
      setSelectedIds((current) => current.filter((id) => !done.includes(id)));
    } finally {
      setBusyId(null);
    }
  };

  const confirmSelected = async () => {
    if (selectedRows.length < 2) return;
    setBusyId('selected');
    setError(null);
    setNotice(null);
    const done: string[] = [];
    try {
      for (const row of selectedRows) {
        await axios.post(
          buildApiUrl(`/expert/transactions/${row._id}/calculation-review/confirm`),
          { note },
          { headers: { Authorization: `Bearer ${token()}` } },
        );
        done.push(row._id);
        setRows((current) => current.map((item) => (
          item._id === row._id ? { ...item, settled: true, settledKilograms: Number(item.co2Emissions || 0) } : item
        )));
      }
      setNotice(`Approved ${done.length} transactions. ${approvalEffect(selectedUser?.name)}`);
      setSelectedIds([]);
      await loadCompanies();
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The selected rows could not be approved.');
      setSelectedIds((current) => current.filter((id) => !done.includes(id)));
    } finally {
      setBusyId(null);
    }
  };

  const askSelected = async (request: { kind: 'details' | 'bill'; question: string }) => {
    if (selectedRows.length < 2) return;
    setBusyId('selected');
    setError(null);
    setNotice(null);
    const done: string[] = [];
    try {
      for (const row of selectedRows) {
        const response = await axios.post(
          buildApiUrl(`/expert/transactions/${row._id}/information-request`),
          request,
          { headers: { Authorization: `Bearer ${token()}` } },
        );
        const informationRequest = response.data?.data?.informationRequest;
        done.push(row._id);
        setRows((current) => current.map((item) => (
          item._id === row._id ? { ...item, informationRequest } : item
        )));
      }
      setNotice(request.kind === 'bill'
        ? `Asked the company for the bill on ${done.length} transactions.`
        : `Asked the company for more information on ${done.length} transactions.`);
      setSelectedIds([]);
    } catch (requestError: any) {
      setError(requestError?.response?.data?.message || 'The request could not be sent for every selected transaction.');
      setSelectedIds((current) => current.filter((id) => !done.includes(id)));
    } finally {
      setBusyId(null);
    }
  };

  const confirmOpen = async (category?: string) => {
    if (!msmeId) return;
    setBusyId(category || 'all');
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl('/expert/calculation-review/confirm-open'),
        { msmeId, note, category: category || undefined },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      setNotice(response.data?.message || 'Open rows confirmed.');
      await loadCompanies();
      await loadRows(msmeId);
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The open rows could not be confirmed.');
    } finally {
      setBusyId(null);
    }
  };

  const askCompany = async (row: ExpertReviewRow, request: { kind: 'details' | 'bill'; question: string }) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/information-request`),
        request,
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const informationRequest = response.data?.data?.informationRequest;
      setNotice(response.data?.message || 'Asked the company for more information.');
      setRows((current) => current.map((item) => (
        item._id === row._id ? { ...item, informationRequest } : item
      )));
    } catch (requestError: any) {
      setError(requestError?.response?.data?.message || 'The request could not be sent.');
    } finally {
      setBusyId(null);
    }
  };

  const cancelRequest = async (row: ExpertReviewRow) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/information-request/cancel`),
        {},
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      setNotice('The request was cancelled. You can correct this row.');
      setRows((current) => current.map((item) => (
        item._id === row._id ? { ...item, informationRequest: null } : item
      )));
    } catch (requestError: any) {
      setError(requestError?.response?.data?.message || 'The request could not be cancelled.');
    } finally {
      setBusyId(null);
    }
  };

  const askAgent = async (row: ExpertReviewRow) => {
    setAskingId(row._id);
    setError(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/correction-assistance`),
        {},
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const assistance = response.data?.data?.assistance?.[0];
      if (!assistance) {
        setError('The correction agent did not return a recommendation.');
        return;
      }
      setAssistanceById((current) => ({ ...current, [row._id]: assistance }));
    } catch (assistError: any) {
      setError(assistError?.response?.data?.message || 'The correction agent could not be reached.');
    } finally {
      setAskingId(null);
    }
  };

  const downloadRows = async () => {
    if (!msmeId) return;
    setDownloading(true);
    setError(null);
    try {
      await downloadUncertainWorkbook(msmeId);
    } catch (downloadError: any) {
      setError(downloadError?.response?.data?.message || 'The uncertain transactions workbook could not be downloaded.');
    } finally {
      setDownloading(false);
    }
  };

  const selected = companies.find((company) => company.msmeId === msmeId);

  return (
    <Paper sx={{ p: 2, mb: 3 }}>
      {onBack ? (
        <Button size="small" sx={{ mb: 1 }} onClick={onBack}>All users</Button>
      ) : null}
      <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.5 }}>
        {selectedUser ? `Uncertain transactions for ${selectedUser.name}` : 'Calculation review by category'}
      </Typography>
      <Box sx={{ mb: 2 }}>
        <ExpertReviewLayoutControl
          value={layout}
          onChange={(next) => {
            writeExpertReviewLayout(next);
            setLayout(next);
          }}
        />
      </Box>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {selectedUser
          ? `${selectedUser.email}${selectedUser.companyName ? ` · ${selectedUser.companyName}` : ''}. ${layout === 'page' ? 'Every open transaction is on this page.' : 'Open one transaction at a time.'} Analytics and report generation for this user use the approved calculation.`
          : `${layout === 'page' ? 'Every open transaction is on this page.' : 'Open one transaction at a time.'} Rupees are not multiplied by 0.001 kg CO2e per INR.`}
      </Typography>
      {error ? <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert> : null}
      {notice ? <Alert severity="success" sx={{ mb: 2 }} onClose={() => setNotice(null)}>{notice}</Alert> : null}
      {loading ? <Typography variant="body2">Loading uncertain transactions…</Typography> : null}
      {selectedUser && !selectedUser.msmeId ? (
        <Typography variant="body2">This user has no company ledger, so there are no transactions to correct.</Typography>
      ) : null}
      {!selectedUser && !loading && companies.length === 0 ? (
        <Typography variant="body2">No company ledger is waiting for a calculation review.</Typography>
      ) : null}
      {!selectedUser && companies.length > 0 ? (
        <Box sx={{ display: 'grid', gap: 1, mb: 2 }}>
          <TextField
            select
            size="small"
            label="Company"
            value={msmeId}
            onChange={(event) => setMsmeId(event.target.value)}
          >
            {companies.map((company) => (
              <MenuItem key={company.msmeId} value={company.msmeId}>
                {`${company.companyName} · ${company.openRequired} open · ${company.counts.withoutCalculation} without calculation · ${company.counts.spendBased} spend-based`}
              </MenuItem>
            ))}
          </TextField>
          {selected ? (
            <Typography variant="body2" color="text.secondary">
              {selected.scope === 'all'
                ? 'This company also asked for review of transactions that already have a calculation.'
                : 'Required review covers rows without a calculation and spend-based rows.'}
            </Typography>
          ) : null}
        </Box>
      ) : null}
      {(selectedUser?.msmeId || (!selectedUser && companies.length > 0)) ? (
        <Box sx={{ display: 'grid', gap: 1, mb: 2 }}>
          <TextField
            size="small"
            label="Note for this review"
            value={note}
            onChange={(event) => setNote(event.target.value)}
          />
          <Button variant="outlined" disabled={!msmeId || downloading} onClick={() => { void downloadRows(); }}>
            {downloading ? 'Downloading' : 'Download this user’s uncertain rows'}
          </Button>
          {bulkBlocked ? (
            <Typography variant="body2" color="text.secondary">
              Enter a quantity on each row that is still at 0 kg CO2e. Those rows are not approved together.
            </Typography>
          ) : null}
          <Button
            variant="outlined"
            disabled={!msmeId || busyId === 'all' || openRows.length === 0 || bulkBlocked}
            onClick={() => { void confirmOpen(); }}
          >
            {busyId === 'all' ? 'Approving' : 'Approve all uncertain rows'}
          </Button>
        </Box>
      ) : null}
      {selectedRows.length >= 2 ? (
        <ExpertReviewTogether
          key={selectedRows.map((row) => row._id).join('|')}
          rows={selectedRows}
          busy={busyId === 'selected'}
          onCorrect={(draft) => { void correctSelected(draft); }}
          onConfirm={() => { void confirmSelected(); }}
          onAsk={(request) => { void askSelected(request); }}
          onClear={() => setSelectedIds([])}
        />
      ) : null}
      {msmeId && rows.length > 0 ? (
        layout === 'page' ? (
          <ExpertReviewPage
            rows={rows}
            busyId={busyId}
            askingId={askingId}
            assistanceById={assistanceById}
            selectedIds={selectedIds}
            onToggle={(id) => setSelectedIds((current) => (
              current.includes(id) ? current.filter((item) => item !== id) : [...current, id]
            ))}
            onSelectSimilar={(row) => setSelectedIds(similarOpenRows(rows, row).map((item) => item._id))}
            onAskAgent={(row) => { void askAgent(row); }}
            onAskCompany={(row, request) => { void askCompany(row, request); }}
            onCancelRequest={(row) => { void cancelRequest(row); }}
            onConfirm={(row) => { void confirmOne(row); }}
            onCorrect={(row, draft) => { void correctOne(row, draft); }}
          />
        ) : (
          <ExpertReviewWizard
            rows={rows}
            busyId={busyId}
            askingId={askingId}
            assistanceById={assistanceById}
            selectedIds={selectedIds}
            onToggle={(id) => setSelectedIds((current) => (
              current.includes(id) ? current.filter((item) => item !== id) : [...current, id]
            ))}
            onSelectSimilar={(row) => setSelectedIds(similarOpenRows(rows, row).map((item) => item._id))}
            onAskAgent={(row) => { void askAgent(row); }}
            onAskCompany={(row, request) => { void askCompany(row, request); }}
            onCancelRequest={(row) => { void cancelRequest(row); }}
            onConfirm={(row) => { void confirmOne(row); }}
            onCorrect={(row, draft) => { void correctOne(row, draft); }}
          />
        )
      ) : null}
      {!loading && msmeId && rows.length === 0 ? (
        <Typography variant="body2">No open rows for this company.</Typography>
      ) : null}
    </Paper>
  );
};

export default ExpertCalculationReview;
