import React, { useState } from 'react';
import {
  Box,
  Button,
  MenuItem,
  Paper,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { REVIEW_CATEGORIES, categoryLabel } from './expertReviewCategories';
import {
  ExpertReviewRow,
  REVIEW_UNITS,
  canApproveAsIs,
  similarityKey,
} from './expertReviewDisplay';

const ExpertReviewTogether: React.FC<{
  rows: ExpertReviewRow[];
  busy: boolean;
  onCorrect: (draft: { category: string; quantity: string; unit: string }) => void;
  onConfirm: () => void;
  onAsk: (request: { kind: 'details' | 'bill'; question: string }) => void;
  onClear: () => void;
}> = ({ rows, busy, onCorrect, onConfirm, onAsk, onClear }) => {
  const first = rows[0];
  const suggested = first?.recommendation;
  const [category, setCategory] = useState(suggested?.category || first?.category || 'other');
  const [quantity, setQuantity] = useState(
    suggested?.quantity != null ? String(suggested.quantity) : '',
  );
  const [unit, setUnit] = useState(suggested?.unit || '');
  const [question, setQuestion] = useState('');
  const categoryValue = REVIEW_CATEGORIES.includes(category as typeof REVIEW_CATEGORIES[number]) ? category : 'other';
  const units = REVIEW_UNITS.includes(unit) || unit === '' ? REVIEW_UNITS : [unit, ...REVIEW_UNITS];
  const mixed = new Set(rows.map(similarityKey)).size > 1;
  const approvable = rows.length > 0 && rows.every(canApproveAsIs);

  return (
    <Paper variant="outlined" sx={{ p: 2, mb: 2 }} data-testid="assess-together">
      <Typography variant="h6" sx={{ fontWeight: 800 }}>
        {`${rows.length} transactions selected`}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
        {mixed
          ? 'These transactions are not the same kind. The quantity and unit below are saved on every selected transaction.'
          : 'These transactions share the same recommendation. The quantity and unit below are saved on every selected transaction.'}
      </Typography>
      <Typography variant="body2" sx={{ mt: 1 }}>
        {rows.map((row) => row.description || 'Untitled voucher').join(' · ')}
      </Typography>
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1.4fr 0.8fr 0.8fr' }, gap: 1, mt: 2 }}>
        <TextField select size="small" label="Category for the selection" value={categoryValue} onChange={(event) => setCategory(event.target.value)}>
          {REVIEW_CATEGORIES.map((item) => <MenuItem key={item} value={item}>{categoryLabel(item)}</MenuItem>)}
        </TextField>
        <TextField size="small" label="Quantity for the selection" value={quantity} onChange={(event) => setQuantity(event.target.value)} />
        <TextField select size="small" label="Unit for the selection" value={unit} onChange={(event) => setUnit(event.target.value)}>
          <MenuItem value="">Choose a unit</MenuItem>
          {units.map((item) => <MenuItem key={item} value={item}>{item}</MenuItem>)}
        </TextField>
      </Box>
      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 2 }}>
        <Button
          variant="contained"
          disabled={busy || quantity === '' || !unit}
          onClick={() => onCorrect({ category: categoryValue, quantity, unit })}
        >
          Correct and approve selected
        </Button>
        {approvable ? (
          <Button variant="outlined" disabled={busy} onClick={onConfirm}>Approve selected</Button>
        ) : null}
        <Button variant="text" onClick={onClear}>Clear selection</Button>
      </Stack>
      <TextField
        fullWidth
        size="small"
        label="What is missing for the selection"
        sx={{ mt: 2 }}
        value={question}
        onChange={(event) => setQuestion(event.target.value)}
      />
      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 1 }}>
        <Button
          variant="outlined"
          disabled={busy || question.trim().length < 8}
          onClick={() => onAsk({ kind: 'details', question: question.trim() })}
        >
          Ask the company about the selection
        </Button>
        <Button
          variant="outlined"
          disabled={busy || question.trim().length < 8}
          onClick={() => onAsk({ kind: 'bill', question: question.trim() })}
        >
          Ask for the bills
        </Button>
      </Stack>
    </Paper>
  );
};

export default ExpertReviewTogether;
