import React, { useMemo, useState } from 'react';
import {
  Box,
  Button,
  Checkbox,
  Chip,
  MenuItem,
  Paper,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { REVIEW_CATEGORIES, categoryLabel } from './expertReviewCategories';
import {
  ExpertReviewRow,
  REVIEW_UNITS,
  canApproveAsIs,
  canSelectForSharedAssessment,
  reviewClassLabel,
  similarOpenRows,
  uncertaintyRank,
  voucherFacts,
} from './expertReviewDisplay';

export type ReviewStep = 'understand' | 'recommendation' | 'correct' | 'send';

const STEP_ORDER: ReviewStep[] = ['understand', 'recommendation', 'correct', 'send'];
const STEP_LABELS: Record<ReviewStep, string> = {
  understand: '1. Transaction',
  recommendation: '2. Recommendation',
  correct: '3. Correct',
  send: '4. Send back',
};

export interface CorrectionAssistanceView {
  needsAssistance: boolean;
  referToRecommendation: boolean;
  message: string;
  apply?: {
    category?: string;
    quantity?: number | null;
    unit?: string;
    factorId?: string;
    factorLabel?: string;
  } | null;
}

const ExpertReviewWizard: React.FC<{
  rows: ExpertReviewRow[];
  busyId: string | null;
  askingId: string | null;
  assistanceById: Record<string, CorrectionAssistanceView>;
  onAskAgent: (row: ExpertReviewRow) => void;
  onAskCompany: (row: ExpertReviewRow, request: { kind: 'details' | 'bill'; question: string }) => void;
  onCancelRequest: (row: ExpertReviewRow) => void;
  onConfirm: (row: ExpertReviewRow) => void;
  onCorrect: (row: ExpertReviewRow, draft: { category: string; quantity: string; unit: string }) => void;
  selectedIds?: string[];
  onToggle?: (id: string) => void;
  onSelectSimilar?: (row: ExpertReviewRow) => void;
}> = ({
  rows,
  busyId,
  askingId,
  assistanceById,
  onAskAgent,
  onAskCompany,
  onCancelRequest,
  onConfirm,
  onCorrect,
  selectedIds = [],
  onToggle,
  onSelectSimilar,
}) => {
  const ordered = useMemo(
    () => [...rows].sort((left, right) => uncertaintyRank(left) - uncertaintyRank(right) || String(left.description).localeCompare(String(right.description))),
    [rows],
  );
  const [activeId, setActiveId] = useState<string | null>(null);
  const [step, setStep] = useState<ReviewStep>('understand');
  const [drafts, setDrafts] = useState<Record<string, { category: string; quantity: string; unit: string }>>({});
  const [questions, setQuestions] = useState<Record<string, string>>({});
  const row = ordered.find((item) => item._id === activeId) || null;
  const openRows = ordered.filter((item) => !item.settled);
  const index = row ? openRows.findIndex((item) => item._id === row._id) : -1;

  const draftFor = (item: ExpertReviewRow) => {
    const saved = drafts[item._id];
    if (saved) return saved;
    const suggested = item.recommendation;
    return {
      category: suggested?.category || item.category || 'other',
      quantity: suggested?.quantity != null
        ? String(suggested.quantity)
        : (item.quantity != null ? String(item.quantity) : ''),
      unit: suggested?.unit || item.unit || '',
    };
  };

  const openRow = (item: ExpertReviewRow) => {
    setActiveId(item._id);
    setStep(item.informationRequest?.status === 'open' ? 'send' : 'understand');
  };

  const applyRecommendation = (item: ExpertReviewRow, apply?: CorrectionAssistanceView['apply']) => {
    const suggested = item.recommendation;
    setDrafts((current) => ({
      ...current,
      [item._id]: {
        category: apply?.category || suggested?.category || item.category || 'other',
        quantity: apply?.quantity != null
          ? String(apply.quantity)
          : (suggested?.quantity != null ? String(suggested.quantity) : (item.quantity != null ? String(item.quantity) : '')),
        unit: apply?.unit || suggested?.unit || item.unit || '',
      },
    }));
    setStep('correct');
  };

  if (!row) {
    return (
      <Stack spacing={1.5}>
        <Typography variant="body2" color="text.secondary">
          {openRows.length
            ? `${openRows.length} transaction${openRows.length === 1 ? '' : 's'} still need a decision. Open one, read it, then use the recommendation or send it back.`
            : 'Every open transaction on this list has a decision.'}
        </Typography>
        {ordered.map((item) => (
          <Paper key={item._id} variant="outlined" sx={{ p: 1.5 }}>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }}>
              <Checkbox
                checked={selectedIds.includes(item._id)}
                disabled={!canSelectForSharedAssessment(item)}
                inputProps={{ 'aria-label': `Select ${item.description || 'this transaction'}` }}
                onChange={() => onToggle?.(item._id)}
              />
              <Box sx={{ flex: 1 }}>
                <Typography variant="subtitle2">{item.description || 'Untitled voucher'}</Typography>
                <Typography variant="caption" color="text.secondary">
                  {reviewClassLabel(item)}
                  {item.settled ? ' · Approved' : item.informationRequest?.status === 'open' ? ' · Waiting for the company' : ''}
                </Typography>
              </Box>
              {similarOpenRows(ordered, item).length > 1 ? (
                <Button size="small" onClick={() => onSelectSimilar?.(item)}>
                  {`Select similar to ${item.description || 'this transaction'}`}
                </Button>
              ) : null}
              <Button size="small" variant="contained" onClick={() => openRow(item)}>
                {item.settled ? 'View' : `Review ${item.description || 'this transaction'}`}
              </Button>
            </Stack>
          </Paper>
        ))}
      </Stack>
    );
  }

  const facts = voucherFacts(row);
  const draft = draftFor(row);
  const assistance = assistanceById[row._id];
  const request = row.informationRequest;
  const waiting = request?.status === 'open';
  const busy = busyId === row._id;
  const units = REVIEW_UNITS.includes(draft.unit) || draft.unit === ''
    ? REVIEW_UNITS
    : [draft.unit, ...REVIEW_UNITS];
  const categoryValue = REVIEW_CATEGORIES.includes(draft.category as typeof REVIEW_CATEGORIES[number])
    ? draft.category
    : 'other';

  return (
    <Stack spacing={2}>
      <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
        <Checkbox
          checked={selectedIds.includes(row._id)}
          disabled={!canSelectForSharedAssessment(row)}
          inputProps={{ 'aria-label': `Select ${row.description || 'this transaction'}` }}
          onChange={() => onToggle?.(row._id)}
        />
        <Button size="small" onClick={() => setActiveId(null)}>All transactions</Button>
        <Typography variant="body2" color="text.secondary">
          {index >= 0 ? `Transaction ${index + 1} of ${openRows.length}` : 'Reviewed'}
        </Typography>
      </Stack>
      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
        {STEP_ORDER.map((item) => (
          <Chip
            key={item}
            label={STEP_LABELS[item]}
            color={step === item ? 'primary' : 'default'}
            variant={step === item ? 'filled' : 'outlined'}
            onClick={() => setStep(item)}
          />
        ))}
      </Stack>

      {step === 'understand' ? (
        <Paper variant="outlined" sx={{ p: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 800 }}>{row.description || 'Untitled voucher'}</Typography>
          <Chip size="small" label={reviewClassLabel(row)} sx={{ mt: 1 }} />
          <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr 1fr' }, gap: 1.5, mt: 2 }}>
            <Fact label="Date" value={facts.when || 'No date'} />
            <Fact label="Amount" value={facts.amount} />
            <Fact label="Vendor" value={facts.vendor} />
          </Box>
          <Typography variant="body1" sx={{ mt: 2, fontWeight: 700 }}>
            {`Current result ${facts.kilograms} kg CO2e`}
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>{facts.factorLine}</Typography>
          <Typography variant="body2" color="text.secondary">{facts.formula}</Typography>
          {facts.subcategory ? (
            <Typography variant="body2" sx={{ mt: 1 }}>{`Subcategory ${facts.subcategory}`}</Typography>
          ) : null}
          <Stack direction="row" spacing={1} sx={{ mt: 2 }}>
            <Button variant="contained" onClick={() => setStep('recommendation')}>See the recommendation</Button>
            <Button variant="text" onClick={() => setStep('send')}>Send back to the company</Button>
          </Stack>
        </Paper>
      ) : null}

      {step === 'recommendation' ? (
        <Paper variant="outlined" sx={{ p: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 800 }}>Recommendation</Typography>
          {row.recommendation ? (
            <>
              <Typography variant="subtitle1" sx={{ mt: 1, fontWeight: 700 }}>{row.recommendation.title}</Typography>
              <Typography variant="body2" sx={{ mt: 1 }}>{row.recommendation.action}</Typography>
              {facts.suggestion ? (
                <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>{facts.suggestion}</Typography>
              ) : null}
            </>
          ) : (
            <Typography variant="body2" sx={{ mt: 1 }}>This row has no stored recommendation yet.</Typography>
          )}
          {assistance ? (
            <Box sx={{ mt: 2 }}>
              <Typography variant="subtitle2">
                {assistance.referToRecommendation ? 'Refer to this recommendation' : 'No parameter change is recommended'}
              </Typography>
              <Typography variant="body2">{assistance.message}</Typography>
              {assistance.apply?.factorLabel ? (
                <Typography variant="body2" sx={{ mt: 0.5 }}>{`Suggested factor ${assistance.apply.factorLabel}`}</Typography>
              ) : null}
            </Box>
          ) : null}
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 2 }}>
            <Button variant="outlined" disabled={busy || askingId === row._id} onClick={() => onAskAgent(row)}>
              {askingId === row._id ? 'Asking the agent' : 'Ask the correction agent'}
            </Button>
            <Button variant="contained" onClick={() => applyRecommendation(row, assistance?.apply || null)}>
              Use this recommendation
            </Button>
            <Button variant="text" onClick={() => setStep('understand')}>Back</Button>
          </Stack>
        </Paper>
      ) : null}

      {step === 'correct' ? (
        <Paper variant="outlined" sx={{ p: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 800 }}>Correct the calculation</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5, mb: 2 }}>
            Enter the category, quantity, and unit. The rupee amount is not the activity.
          </Typography>
          {waiting ? (
            <Typography variant="body2">This row is waiting for the company. Correct it after the reply arrives.</Typography>
          ) : (
            <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1.4fr 0.8fr 0.8fr' }, gap: 1 }}>
              <TextField
                select
                size="small"
                label="Category"
                value={categoryValue}
                onChange={(event) => setDrafts((current) => ({ ...current, [row._id]: { ...draft, category: event.target.value } }))}
              >
                {REVIEW_CATEGORIES.map((item) => <MenuItem key={item} value={item}>{categoryLabel(item)}</MenuItem>)}
              </TextField>
              <TextField
                size="small"
                label="Quantity"
                value={draft.quantity}
                onChange={(event) => setDrafts((current) => ({ ...current, [row._id]: { ...draft, quantity: event.target.value } }))}
              />
              <TextField
                select
                size="small"
                label="Unit"
                value={draft.unit}
                onChange={(event) => setDrafts((current) => ({ ...current, [row._id]: { ...draft, unit: event.target.value } }))}
              >
                <MenuItem value="">Choose a unit</MenuItem>
                {units.map((unit) => <MenuItem key={unit} value={unit}>{unit}</MenuItem>)}
              </TextField>
            </Box>
          )}
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 2 }}>
            <Button
              variant="contained"
              disabled={busy || waiting || draft.quantity === '' || !draft.unit}
              onClick={() => onCorrect(row, { ...draft, category: categoryValue })}
            >
              Correct and approve
            </Button>
            {canApproveAsIs(row) ? (
              <Button variant="outlined" disabled={busy} onClick={() => onConfirm(row)}>Approve</Button>
            ) : null}
            <Button variant="text" onClick={() => setStep('send')}>Send back to the company</Button>
          </Stack>
        </Paper>
      ) : null}

      {step === 'send' ? (
        <Paper variant="outlined" sx={{ p: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 800 }}>Send back to the company</Typography>
          {request ? (
            <Box sx={{ mt: 1 }}>
              <Typography variant="subtitle2">
                {request.kind === 'bill' ? 'Asked the company to upload the bill' : 'Asked the company for more information'}
              </Typography>
              <Typography variant="body2">{request.question}</Typography>
              {request.status === 'answered' ? (
                <Typography variant="body2" sx={{ mt: 0.5 }}>
                  {`Company reply: ${request.reply || 'No written reply.'}${request.documentName ? ` Bill: ${request.documentName}.` : ''}`}
                </Typography>
              ) : (
                <Typography variant="body2" sx={{ mt: 0.5 }}>
                  Carbon stays unchanged until the company replies. Then review the reply and correct the calculation.
                </Typography>
              )}
              {waiting ? (
                <Button sx={{ mt: 1 }} variant="text" disabled={busy} onClick={() => onCancelRequest(row)}>Cancel this request</Button>
              ) : null}
            </Box>
          ) : (
            <>
              <TextField
                fullWidth
                size="small"
                label="What is missing"
                sx={{ mt: 2 }}
                value={questions[row._id] || ''}
                placeholder="The bill does not show the diesel litres"
                onChange={(event) => setQuestions((current) => ({ ...current, [row._id]: event.target.value }))}
              />
              <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 2 }}>
                <Button
                  variant="outlined"
                  disabled={busy || (questions[row._id] || '').trim().length < 8}
                  onClick={() => onAskCompany(row, { kind: 'details', question: (questions[row._id] || '').trim() })}
                >
                  Ask for more information
                </Button>
                <Button
                  variant="outlined"
                  disabled={busy || (questions[row._id] || '').trim().length < 8}
                  onClick={() => onAskCompany(row, { kind: 'bill', question: (questions[row._id] || '').trim() })}
                >
                  Ask for the bill
                </Button>
              </Stack>
            </>
          )}
          <Button sx={{ mt: 2 }} variant="text" onClick={() => setStep('understand')}>Back to the transaction</Button>
        </Paper>
      ) : null}

      {row.settled ? (
        <Typography variant="body2">{`Approved. ${Number(row.settledKilograms ?? row.co2Emissions) || 0} kg CO2e.`}</Typography>
      ) : null}
    </Stack>
  );
};

const Fact: React.FC<{ label: string; value: string }> = ({ label, value }) => (
  <Box sx={{ p: 1.25, borderRadius: 1, bgcolor: 'grey.100' }}>
    <Typography variant="caption" color="text.secondary">{label}</Typography>
    <Typography variant="body2" sx={{ fontWeight: 700 }}>{value}</Typography>
  </Box>
);

export default ExpertReviewWizard;
