export const REVIEW_CATEGORIES = [
  'raw_materials',
  'energy',
  'transportation',
  'waste_management',
  'water',
  'equipment',
  'maintenance',
  'services',
  'utilities',
  'telecom',
  'other',
] as const;

export const CATEGORY_LABELS: Record<string, string> = {
  raw_materials: 'Purchased materials',
  energy: 'Energy and fuel',
  transportation: 'Transport',
  waste_management: 'Waste',
  water: 'Water',
  equipment: 'Equipment',
  maintenance: 'Maintenance',
  services: 'Services',
  utilities: 'Utilities',
  telecom: 'Telecom',
  other: 'Unclassified purchases',
};

export const categoryLabel = (category?: string) => (
  CATEGORY_LABELS[category || 'other'] || category || 'Unclassified purchases'
);

export const groupByCategory = <T extends { category?: string }>(rows: T[]) => {
  const groups = new Map<string, T[]>();
  rows.forEach((row) => {
    const key = row.category && CATEGORY_LABELS[row.category] ? row.category : (row.category || 'other');
    const bucket = groups.get(key) || [];
    bucket.push(row);
    groups.set(key, bucket);
  });
  const known = REVIEW_CATEGORIES.filter((key) => groups.has(key));
  const extra = Array.from(groups.keys()).filter((key) => !REVIEW_CATEGORIES.includes(key as typeof REVIEW_CATEGORIES[number]));
  const order: string[] = [...known, ...extra];
  return order.map((key) => ({
    key,
    label: categoryLabel(key),
    rows: groups.get(key) || [],
  }));
};

export const formatVoucherDate = (value?: string) => {
  if (!value) return '';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return '';
  return parsed.toLocaleDateString('en-IN', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    timeZone: 'Asia/Kolkata',
  });
};
