import React, { useMemo, useState } from 'react';
import {
  Box,
  Button,
  Checkbox,
  Chip,
  MenuItem,
  Paper,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { REVIEW_CATEGORIES, categoryLabel } from './expertReviewCategories';
import {
  ExpertReviewRow,
  REVIEW_UNITS,
  canApproveAsIs,
  canSelectForSharedAssessment,
  reviewClassLabel,
  reviewFormulaLabel,
  similarOpenRows,
  uncertaintyRank,
  voucherFacts,
} from './expertReviewDisplay';
import { CorrectionAssistanceView } from './ExpertReviewWizard';

const ExpertReviewPage: React.FC<{
  rows: ExpertReviewRow[];
  busyId: string | null;
  askingId: string | null;
  assistanceById: Record<string, CorrectionAssistanceView>;
  onAskAgent: (row: ExpertReviewRow) => void;
  onAskCompany: (row: ExpertReviewRow, request: { kind: 'details' | 'bill'; question: string }) => void;
  onCancelRequest: (row: ExpertReviewRow) => void;
  onConfirm: (row: ExpertReviewRow) => void;
  onCorrect: (row: ExpertReviewRow, draft: { category: string; quantity: string; unit: string }) => void;
  selectedIds?: string[];
  onToggle?: (id: string) => void;
  onSelectSimilar?: (row: ExpertReviewRow) => void;
}> = ({
  rows,
  busyId,
  askingId,
  assistanceById,
  onAskAgent,
  onAskCompany,
  onCancelRequest,
  onConfirm,
  onCorrect,
  selectedIds = [],
  onToggle,
  onSelectSimilar,
}) => {
  const ordered = useMemo(
    () => [...rows].sort((left, right) => uncertaintyRank(left) - uncertaintyRank(right) || String(left.description).localeCompare(String(right.description))),
    [rows],
  );

  return (
    <Stack spacing={1.5}>
      <Typography variant="body2" color="text.secondary">
        Every open transaction is on this page. Read it, use the recommendation, correct the quantity, or send it back.
      </Typography>
      {ordered.map((row) => (
        <PageRow
          key={row._id}
          row={row}
          busy={busyId === row._id}
          asking={askingId === row._id}
          assistance={assistanceById[row._id]}
          selected={selectedIds.includes(row._id)}
          similarCount={similarOpenRows(ordered, row).length}
          onToggle={() => onToggle?.(row._id)}
          onSelectSimilar={() => onSelectSimilar?.(row)}
          onAskAgent={() => onAskAgent(row)}
          onAskCompany={(request) => onAskCompany(row, request)}
          onCancelRequest={() => onCancelRequest(row)}
          onConfirm={() => onConfirm(row)}
          onCorrect={(draft) => onCorrect(row, draft)}
        />
      ))}
    </Stack>
  );
};

const PageRow: React.FC<{
  row: ExpertReviewRow;
  busy: boolean;
  asking: boolean;
  assistance?: CorrectionAssistanceView;
  selected: boolean;
  similarCount: number;
  onToggle: () => void;
  onSelectSimilar: () => void;
  onAskAgent: () => void;
  onAskCompany: (request: { kind: 'details' | 'bill'; question: string }) => void;
  onCancelRequest: () => void;
  onConfirm: () => void;
  onCorrect: (draft: { category: string; quantity: string; unit: string }) => void;
}> = ({ row, busy, asking, assistance, selected, similarCount, onToggle, onSelectSimilar, onAskAgent, onAskCompany, onCancelRequest, onConfirm, onCorrect }) => {
  const suggested = row.recommendation;
  const [category, setCategory] = useState(suggested?.category || row.category || 'other');
  const [quantity, setQuantity] = useState(
    suggested?.quantity != null
      ? String(suggested.quantity)
      : (row.quantity != null ? String(row.quantity) : ''),
  );
  const [unit, setUnit] = useState(suggested?.unit || row.unit || '');
  const [question, setQuestion] = useState('');
  const facts = voucherFacts(row);
  const request = row.informationRequest;
  const waiting = request?.status === 'open';
  const units = REVIEW_UNITS.includes(unit) || unit === '' ? REVIEW_UNITS : [unit, ...REVIEW_UNITS];
  const categoryValue = REVIEW_CATEGORIES.includes(category as typeof REVIEW_CATEGORIES[number]) ? category : 'other';

  const applyRecommendation = () => {
    const apply = assistance?.apply;
    if (apply?.category) setCategory(apply.category);
    else if (suggested?.category) setCategory(suggested.category);
    if (apply?.quantity != null) setQuantity(String(apply.quantity));
    else if (suggested?.quantity != null) setQuantity(String(suggested.quantity));
    if (apply?.unit) setUnit(apply.unit);
    else if (suggested?.unit) setUnit(suggested.unit);
  };

  return (
    <Paper variant="outlined" sx={{ p: 1.5 }}>
      <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
        <Checkbox
          checked={selected}
          disabled={!canSelectForSharedAssessment(row)}
          inputProps={{ 'aria-label': `Select ${row.description || 'this transaction'}` }}
          onChange={onToggle}
        />
        <Typography variant="subtitle2">{row.description || 'Untitled voucher'}</Typography>
        <Chip size="small" label={reviewClassLabel(row)} />
        {similarCount > 1 ? (
          <Button size="small" onClick={onSelectSimilar}>{`Select similar to ${row.description || 'this transaction'}`}</Button>
        ) : null}
      </Stack>
      <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
        {[facts.when, facts.vendor, facts.amount, facts.subcategory ? `Subcategory ${facts.subcategory}` : ''].filter(Boolean).join(' · ')}
      </Typography>
      <Typography variant="body2" sx={{ mt: 0.5 }}>
        {`Current result ${facts.kilograms} kg CO2e · ${facts.factorLine} · ${reviewFormulaLabel(row.formula)}`}
      </Typography>
      {suggested ? (
        <Box sx={{ mt: 1 }}>
          <Typography variant="subtitle2">{suggested.title}</Typography>
          <Typography variant="body2">{suggested.action}</Typography>
          {facts.suggestion ? <Typography variant="body2" color="text.secondary">{facts.suggestion}</Typography> : null}
        </Box>
      ) : null}
      {assistance ? (
        <Box sx={{ mt: 1 }}>
          <Typography variant="subtitle2">
            {assistance.referToRecommendation ? 'Refer to this recommendation' : 'No parameter change is recommended'}
          </Typography>
          <Typography variant="body2">{assistance.message}</Typography>
        </Box>
      ) : null}
      {row.settled ? (
        <Typography variant="body2" sx={{ mt: 1 }}>{`Approved. ${Number(row.settledKilograms ?? row.co2Emissions) || 0} kg CO2e.`}</Typography>
      ) : null}
      {waiting || row.settled ? null : (
        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1.4fr 0.8fr 0.8fr' }, gap: 1, mt: 1 }}>
          <TextField select size="small" label="Category" value={categoryValue} onChange={(event) => setCategory(event.target.value)}>
            {REVIEW_CATEGORIES.map((item) => <MenuItem key={item} value={item}>{categoryLabel(item)}</MenuItem>)}
          </TextField>
          <TextField size="small" label="Quantity" value={quantity} onChange={(event) => setQuantity(event.target.value)} />
          <TextField select size="small" label="Unit" value={unit} onChange={(event) => setUnit(event.target.value)}>
            <MenuItem value="">Choose a unit</MenuItem>
            {units.map((item) => <MenuItem key={item} value={item}>{item}</MenuItem>)}
          </TextField>
        </Box>
      )}
      {row.settled ? null : (
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 1 }}>
          {waiting ? (
            <Button variant="text" disabled={busy} onClick={onCancelRequest}>Cancel this request</Button>
          ) : (
            <>
              <Button variant="outlined" disabled={busy || asking} onClick={onAskAgent}>
                {asking ? 'Asking the agent' : 'Ask the correction agent'}
              </Button>
              <Button variant="outlined" disabled={busy} onClick={applyRecommendation}>Use this recommendation</Button>
              {canApproveAsIs(row) ? (
                <Button variant="outlined" disabled={busy} onClick={onConfirm}>Approve</Button>
              ) : null}
              <Button
                variant="contained"
                disabled={busy || quantity === '' || !unit}
                onClick={() => onCorrect({ category: categoryValue, quantity, unit })}
              >
                Correct and approve
              </Button>
            </>
          )}
        </Stack>
      )}
      {row.settled ? null : request ? (
        <Box sx={{ mt: 1 }}>
          <Typography variant="subtitle2">
            {request.kind === 'bill' ? 'Asked the company to upload the bill' : 'Asked the company for more information'}
          </Typography>
          <Typography variant="body2">{request.question}</Typography>
          {request.status === 'answered' ? (
            <Typography variant="body2">{`Company reply: ${request.reply || 'No written reply.'}${request.documentName ? ` Bill: ${request.documentName}.` : ''}`}</Typography>
          ) : (
            <Typography variant="body2">Carbon stays unchanged until the company replies.</Typography>
          )}
        </Box>
      ) : (
        <Box sx={{ mt: 1 }}>
          <TextField
            fullWidth
            size="small"
            label="What is missing"
            value={question}
            placeholder="The bill does not show the diesel litres"
            onChange={(event) => setQuestion(event.target.value)}
          />
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 1 }}>
            <Button
              variant="outlined"
              disabled={busy || question.trim().length < 8}
              onClick={() => onAskCompany({ kind: 'details', question: question.trim() })}
            >
              Ask for more information
            </Button>
            <Button
              variant="outlined"
              disabled={busy || question.trim().length < 8}
              onClick={() => onAskCompany({ kind: 'bill', question: question.trim() })}
            >
              Ask for the bill
            </Button>
          </Stack>
        </Box>
      )}
    </Paper>
  );
};

export default ExpertReviewPage;
