import { categoryLabel, formatVoucherDate } from './expertReviewCategories';

export interface ExpertReviewRow {
  _id: string;
  date?: string;
  description?: string;
  amount?: number;
  currency?: string;
  category?: string;
  subcategory?: string;
  quantity?: number;
  unit?: string;
  vendorName?: string;
  calculationClass?: string;
  formula?: string;
  co2Emissions?: number;
  quantificationMethod?: string;
  factorId?: string;
  factor?: number | null;
  factorUnit?: string;
  recommendation?: {
    id?: string;
    title: string;
    action: string;
    category?: string;
    unit?: string;
    quantity?: number | null;
    factorId?: string;
    factorLabel?: string;
  } | null;
  settled?: boolean;
  settledKilograms?: number;
  priorKilograms?: number;
  informationRequest?: {
    status: 'open' | 'answered';
    kind: 'details' | 'bill';
    question: string;
    reply?: string;
    documentName?: string;
  } | null;
}

export const reviewClassLabel = (row: ExpertReviewRow) => {
  const method = String(row.quantificationMethod || '').toLowerCase();
  const formula = String(row.formula || '');
  if (
    method.includes('admin_emission_review')
    || formula === 'adminEmissionReview'
    || row.factorId === 'activity_classification_required'
  ) {
    return 'Needs expert review';
  }
  if (row.calculationClass === 'spend_based') return 'Spend-based';
  if (row.calculationClass === 'calculated') return 'With calculation';
  return 'Without calculation';
};

export const reviewFormulaLabel = (formula?: string) => {
  if (!formula || formula === 'adminEmissionReview') return 'Waiting for a named activity';
  if (formula === 'activityQuantity * emissionFactor') return 'Quantity × emission factor';
  if (formula === '(spendAmount / unitPrice) * emissionFactor') return 'Rupees ÷ unit price × emission factor';
  if (formula === '0') return 'Result is 0 kg CO2e';
  return formula;
};

export const factorNeedsActivity = (factorId?: string) => (
  !factorId
  || factorId === 'spend_generic'
  || factorId === 'activity_classification_required'
);

export const uncertaintyRank = (row: ExpertReviewRow) => {
  if (reviewClassLabel(row) === 'Needs expert review') return 0;
  const recommendationId = String(row.recommendation?.id || '');
  if (row.category === 'maintenance' || /maintenance|refrigerant/.test(recommendationId)) return 1;
  if (row.calculationClass === 'spend_based' || reviewClassLabel(row) === 'Spend-based') return 2;
  return 3;
};

export const lacksActivityQuantity = (row: ExpertReviewRow) => {
  const quantity = Number(row.quantity);
  const kilograms = Number(row.co2Emissions || 0);
  return !row.settled && !(kilograms > 0) && !(Number.isFinite(quantity) && quantity > 0);
};

export const similarityKey = (row: ExpertReviewRow) => {
  if (row.recommendation?.id) return `recommendation:${row.recommendation.id}`;
  if (row.subcategory) return `subcategory:${row.subcategory}`;
  return `category:${row.category || 'other'}:${reviewClassLabel(row)}`;
};

export const canSelectForSharedAssessment = (row: ExpertReviewRow) => (
  !row.settled && row.informationRequest?.status !== 'open'
);

export const similarOpenRows = (rows: ExpertReviewRow[], row: ExpertReviewRow) => {
  const key = similarityKey(row);
  return rows.filter((item) => canSelectForSharedAssessment(item) && similarityKey(item) === key);
};

export const canApproveAsIs = (row: ExpertReviewRow) => (
  !row.settled
  && !factorNeedsActivity(row.factorId)
  && Number(row.co2Emissions || 0) > 0
  && Number(row.quantity) > 0
  && Boolean(row.unit)
);

export const voucherFacts = (row: ExpertReviewRow) => ({
  when: formatVoucherDate(row.date),
  amount: row.amount != null ? `${row.amount} ${row.currency || 'INR'}` : 'No amount',
  vendor: row.vendorName || 'No vendor',
  subcategory: row.subcategory || '',
  kilograms: Number(row.priorKilograms ?? row.co2Emissions) || 0,
  factorLine: factorNeedsActivity(row.factorId)
    ? 'No activity factor yet. The result stays at 0 kg CO2e until you enter the quantity and unit.'
    : `Factor ${row.factorId}${row.factor != null ? ` · ${row.factor} ${row.factorUnit || ''}`.trim() : ''}`,
  formula: reviewFormulaLabel(row.formula),
  suggestion: row.recommendation
    ? [
      `Suggested category ${categoryLabel(row.recommendation.category)}`,
      `Suggested quantity ${row.recommendation.quantity == null ? '—' : String(row.recommendation.quantity)}`,
      `Suggested unit ${row.recommendation.unit || '—'}`,
      row.recommendation.factorLabel ? `Suggested factor ${row.recommendation.factorLabel}` : '',
    ].filter(Boolean).join(' · ')
    : '',
});

export const REVIEW_UNITS = ['kg', 'L', 'kWh', 'visit', 'km', 't', 'm3'];
