export type ExpertReviewLayout = 'page' | 'steps';

const STORAGE_KEY = 'expert-review-layout';

export const readExpertReviewLayout = (): ExpertReviewLayout => (
  localStorage.getItem(STORAGE_KEY) === 'page' ? 'page' : 'steps'
);

export const writeExpertReviewLayout = (layout: ExpertReviewLayout) => {
  localStorage.setItem(STORAGE_KEY, layout);
};
