import React from 'react';
import { ToggleButton, ToggleButtonGroup, Typography } from '@mui/material';
import { ExpertReviewLayout } from './expertReviewLayout';

const ExpertReviewLayoutControl: React.FC<{
  value: ExpertReviewLayout;
  onChange: (layout: ExpertReviewLayout) => void;
}> = ({ value, onChange }) => (
  <div>
    <Typography variant="caption" color="text.secondary" component="div" sx={{ mb: 0.5 }}>
      Review layout. This choice stays on this browser.
    </Typography>
    <ToggleButtonGroup
      exclusive
      size="small"
      color="primary"
      aria-label="Review layout"
      value={value}
      onChange={(_event, next: ExpertReviewLayout | null) => {
        if (next) onChange(next);
      }}
    >
      <ToggleButton value="page" aria-label="One page">One page</ToggleButton>
      <ToggleButton value="steps" aria-label="Step by step">Step by step</ToggleButton>
    </ToggleButtonGroup>
  </div>
);

export default ExpertReviewLayoutControl;
